import asyncio
import inspect
from functools import wraps, partial
from typing import Any

if sys.version_info >= (3, 13):
    from inspect import iscoroutinefunction
else:
    from asyncio import iscoroutinefunction

import sys

def is_async_callable(call: Any) -> bool:
    current = call
    while True:
        if iscoroutinefunction(current):
            return True
        if hasattr(current, "__wrapped__"):
            current = current.__wrapped__
            continue
        if isinstance(current, partial):
            current = current.func
            continue
        dunder_call = getattr(current, "__call__", None)
        if dunder_call is not None and dunder_call is not current:
            current = dunder_call
            continue
        break
    return False

def test():
    def original():
        return "hello"

    @wraps(original)
    async def wrapper():
        return original()

    print(f"Case 1 (Wrapped async): {is_async_callable(wrapper)}") # Expected: True

    p_wrapper = partial(wrapper)
    print(f"Case 2 (Partial of wrapped async): {is_async_callable(p_wrapper)}") # Expected: True

    async def async_func():
        return "hello"
    p_async = partial(async_func)

    @wraps(p_async)
    def wrapper_p(x=None):
        return p_async(x)

    print(f"Case 3 (Wrapped partial of async): {is_async_callable(wrapper_p)}") # Expected: True

    p_wrapper_p = partial(wrapper_p)
    print(f"Case 4 (Partial of wrapped partial of async): {is_async_callable(p_wrapper_p)}") # Expected: True

    class AsyncCallable:
        async def __call__(self):
            return "hello"

    ac = AsyncCallable()
    print(f"Case 5 (Async callable instance): {is_async_callable(ac)}") # Expected: True

    class SyncCallable:
        def __call__(self):
            return "hello"

    sc = SyncCallable()
    print(f"Case 6 (Sync callable instance): {is_async_callable(sc)}") # Expected: False

if __name__ == "__main__":
    test()
